head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setStartRowNumber]<br/>rowNumVisible=true 일때 표시되는 RowNum Column 의 시작 인덱스를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 RowNum Column 의 시작 인덱스를 설정할 수 있어야 합니다.",
        "파라미터값은 인덱스로 처리되며 실제 RowNum Column 에 표시되는 Row 번호는 파라미터값+1 부터 시작되어야 합니다.",
        "GridView 에 표시되는 Row 데이터는 변경되지 않으며 Row 번호만 변경되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        rowNumVisible: true,
        rowNumHeaderValue: "No.",
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);
}



scwin.btn_setStartRowNumber_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());

    target1.setStartRowNumber(rowIndex);

    // td[id*='target1_headerRowNumber_bodyRow'] 의 text 로 RowNum 표시값 확인
    let rowNumCells = document.querySelectorAll("td[id*='target1_headerRowNumber_bodyRow']");
    let rowNumValues = [];
    rowNumCells.forEach(function (cell) {
        if (cell.textContent.trim() !== '') {
            rowNumValues.push(cell.textContent.trim());
        }
    });

    wf_body_bottom.getObj("scwin").setReturnValue("RowNum 표시값 : " + rowNumValues.join(", "));

    // getAllDisplayJSON 으로 GridView 데이터 확인
    let displayData = target1.getAllDisplayJSON();
    wf_body_bottom.getObj("scwin").setReturnValue("getAllDisplayJSON() : " + JSON.stringify(displayData));
}
